      AND pt.tool_key NOT IN ('s3test57761/echo_test_s3', 's3test57761/echo_demo')) THEN
    RAISE EXCEPTION 'audit drift: un-audited MIME rows present';
  END IF;
  -- Retired schema preconditions.
  IF to_regclass('user_plans') IS NULL THEN
    RAISE EXCEPTION 'precondition: user_plans table unexpectedly absent';
  END IF;
  IF (SELECT count(*) FROM user_plans) <> 0 THEN
    RAISE EXCEPTION 'precondition: user_plans not empty';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                 WHERE table_name='packages' AND column_name='legacy_creem_product_id') THEN
    RAISE EXCEPTION 'precondition: packages.legacy_creem_product_id unexpectedly absent';
  END IF;
  IF (SELECT count(*) FROM packages WHERE legacy_creem_product_id IS NOT NULL) <> 0 THEN
    RAISE EXCEPTION 'precondition: packages.legacy_creem_product_id has non-null values';
  END IF;
  -- Free must not exist yet (exact insert below refuses conflict).
  IF EXISTS (SELECT 1 FROM plans WHERE code='free') THEN
    RAISE EXCEPTION 'precondition: plans.free already exists';
  END IF;
  -- Production plan set must be exactly plus + pro (audited 2026-09-16).
  IF (SELECT string_agg(code, ',' ORDER BY code) FROM plans) <> 'plus,pro' THEN
    RAISE EXCEPTION 'precondition: plans set is not exactly plus,pro';
  END IF;
END $$;

-- ═══ 1. plans current-schema columns ═══

ALTER TABLE plans ADD COLUMN ingress_files_24h INTEGER NOT NULL DEFAULT 0;
ALTER TABLE plans ADD COLUMN ingress_bytes_24h BIGINT NOT NULL DEFAULT 0;
ALTER TABLE plans ADD COLUMN expiry_days INTEGER[] NOT NULL DEFAULT ARRAY[]::INTEGER[];
ALTER TABLE plans ADD COLUMN download_limits INTEGER[] NOT NULL DEFAULT ARRAY[]::INTEGER[];
ALTER TABLE plans ADD COLUMN badge_key TEXT;

-- ═══ 2. Plus/Pro entitlement + badge normalization (ONLY these fields) ═══
-- Never touches price_cents / monthly_credits / creem_product_id /
-- sort_order / active / currency.

UPDATE plans SET
  badge_key = 'tier_plus',
  ingress_files_24h = 500,
  ingress_bytes_24h = 5368709120,
  expiry_days = ARRAY[1,3,7,30],
  download_limits = ARRAY[1,10,50,100,200,1000]
WHERE code = 'plus';

UPDATE plans SET
  badge_key = 'tier_pro',
  ingress_files_24h = 2000,
  ingress_bytes_24h = 21474836480,
  expiry_days = ARRAY[1,3,7,30],
  download_limits = ARRAY[1,10,50,100,200,1000]
WHERE code = 'pro';

-- ═══ 3. Free row — exact current-config insert ═══
-- Values mirror the code bootstrap with production env:
--   FLASHSHARE_DAILY_UPLOADS=100, FLASHSHARE_DAILY_MB=1024 (→ 1073741824 B).

INSERT INTO plans (code, name, monthly_credits, period_days, period,
                    price_cents, currency, sort_order, active, badge_key,
                    ingress_files_24h, ingress_bytes_24h,
                    expiry_days, download_limits,
                    created_at, updated_at)
VALUES ('free', 'Free', 0, 30, 'monthly', 0, 'USD', 0, TRUE, 'tier_free',
        100, 1073741824,
        ARRAY[1,3,7], ARRAY[1,10,50,100,200],
        EXTRACT(EPOCH FROM now())::BIGINT, EXTRACT(EPOCH FROM now())::BIGINT);

-- ═══ 4. Two real unlisted tools — exact compare-and-set ═══

DO $$
BEGIN
  IF (SELECT visibility FROM platform_tools WHERE tool_key = 's3test57761/echo_test_s3')
     <> 'unlisted'
     OR (SELECT accept_json FROM platform_tools WHERE tool_key = 's3test57761/echo_test_s3')
        IS DISTINCT FROM '["application/json"]' THEN
    RAISE EXCEPTION 'compare-and-set: echo_test_s3 drifted from audit';
  END IF;
  IF (SELECT visibility FROM platform_tools WHERE tool_key = 's3test57761/echo_demo')
     <> 'unlisted'
     OR (SELECT accept_json FROM platform_tools WHERE tool_key = 's3test57761/echo_demo')
        IS DISTINCT FROM '["application/json", "text/plain"]' THEN
    RAISE EXCEPTION 'compare-and-set: echo_demo drifted from audit';
  END IF;
END $$;

UPDATE platform_tools SET accept_json = '[".json"]',
       updated_at = EXTRACT(EPOCH FROM now())::BIGINT
WHERE tool_key = 's3test57761/echo_test_s3'
  AND accept_json = '["application/json"]';

UPDATE platform_tools SET accept_json = '[".json",".txt"]',
       updated_at = EXTRACT(EPOCH FROM now())::BIGINT
WHERE tool_key = 's3test57761/echo_demo'
  AND accept_json = '["application/json", "text/plain"]';

